// NULL-tolerant scan buffer for carManufacturerScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type carManufacturerPreloadBuf struct {
	ID        null.Val[int32]
	Name      null.Val[string]
	IsActive  null.Val[bool]
	CreatedAt null.Val[time.Time]
	UpdatedAt null.Val[time.Time]
	CreatedBy null.Val[string]
	UpdatedBy null.Val[string]
}

// carManufacturerScanMapperNullable maps the preloaded carManufacturer
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func carManufacturerScanMapperNullable(prefix string) scan.Mapper[*CarManufacturer] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*CarManufacturer, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *carManufacturerPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.Name }})
			case "is_active":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.IsActive }})
			case "created_at":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.UpdatedAt }})
			case "created_by":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.CreatedBy }})
			case "updated_by":
				targets = append(targets, target{i, func(b *carManufacturerPreloadBuf) any { return &b.UpdatedBy }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(carManufacturerPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*CarManufacturer, error) {
				buf := link.(*carManufacturerPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.IsActive.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) &&
					!(buf.CreatedBy.IsValue()) &&
					!(buf.UpdatedBy.IsValue()) {
					return nil, nil
				}

				o := new(CarManufacturer)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.IsActive.IsValue() {
					o.IsActive = buf.IsActive.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				if buf.CreatedBy.IsValue() {
					o.CreatedBy = buf.CreatedBy.MustGet()
				}
				if buf.UpdatedBy.IsValue() {
					o.UpdatedBy = buf.UpdatedBy.MustGet()
				}
				return o, nil
			}
	}
}

func (o *CarManufacturer) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "ManufacturerCarModels":
		rels, ok := retrieved.(CarModelSlice)
		if !ok {
			return fmt.Errorf("carManufacturer cannot load %T as %q", retrieved, name)
		}

		o.R.ManufacturerCarModels = rels
		o.R.Loaded.ManufacturerCarModels = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ManufacturerCarManufacturer = o
				rel.R.Loaded.ManufacturerCarManufacturer = true
			}
		}
		return nil
	default:
		return fmt.Errorf("carManufacturer has no relationship %q", name)
	}
}

