// LoadManufacturerCarModels loads the carManufacturer's ManufacturerCarModels into the .R struct
func (o *CarManufacturer) LoadManufacturerCarModels(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ManufacturerCarModels = nil
	o.R.Loaded.ManufacturerCarModels = false

	related, err := o.ManufacturerCarModels(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.ManufacturerCarManufacturer = o
		rel.R.Loaded.ManufacturerCarManufacturer = true
	}

	o.R.ManufacturerCarModels = related
	o.R.Loaded.ManufacturerCarModels = true
	return nil
}

// LoadManufacturerCarModels loads the carManufacturer's ManufacturerCarModels into the .R struct
func (os CarManufacturerSlice) LoadManufacturerCarModels(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	carModels, err := os.ManufacturerCarModels(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ManufacturerCarModels = nil
		o.R.Loaded.ManufacturerCarModels = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	carManufacturerByKey := make(map[int32][]*CarManufacturer, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		carManufacturerByKey[o.ID] = append(carManufacturerByKey[o.ID], o)
	}

	for _, rel := range carModels {

		owners, ok := carManufacturerByKey[rel.ManufacturerID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.ManufacturerCarManufacturer = o
			rel.R.Loaded.ManufacturerCarManufacturer = true

			o.R.ManufacturerCarModels = append(o.R.ManufacturerCarModels, rel)

		}
	}

	return nil
}

